-- the L1-L5 ladder, a property of the track
insert into capability_level (track_id, level, level_name, requirement, qualification, experience, certification, test_score, evidence)
select t.id, v.lvl, v.nm, v.req, v.qual, v.exp, v.cert, v.score, v.ev from (values
